/**
 * Bank Transaction Actions API
 * POST /api/accounting/bank-transactions-action
 *   action: match | unmatch | exclude | auto_match | allocate | delete | update_notes
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  matchTransaction,
  unmatchTransaction,
  excludeTransaction,
  autoMatchTransactions,
  allocateTransaction,
  splitAllocateTransaction,
  deleteTransactions,
  bulkAcceptTransactions,
  reverseReconciledTransaction,
  type AllocationType,
  type SplitLine,
} from '@/modules/accounting/services/bankReconciliationService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const { action, bankTransactionId, journalLineId, bankAccountId, reconciliationId, contraAccountId, description, allocationType, entityId, vatCode, excludeReason, cc1Id, cc2Id, buId } = req.body;
    // @ts-expect-error — auth middleware attaches user
    const userId: string = req.user?.id || req.user?.userId || 'system';

    if (!action) return apiResponse.badRequest(res, 'action is required');

    switch (action) {
      case 'match': {
        if (!bankTransactionId || !journalLineId) {
          return apiResponse.badRequest(res, 'bankTransactionId and journalLineId are required');
        }
        const tx = await matchTransaction(companyId, bankTransactionId, journalLineId, reconciliationId);
        return apiResponse.success(res, tx);
      }
      case 'unmatch': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await unmatchTransaction(companyId, bankTransactionId);
        return apiResponse.success(res, tx);
      }
      case 'exclude': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
        const tx = await excludeTransaction(
          companyId, bankTransactionId,
          typeof excludeReason === 'string' ? excludeReason : undefined,
        );
        return apiResponse.success(res, tx);
      }
      case 'auto_match': {
        if (!bankAccountId) return apiResponse.badRequest(res, 'bankAccountId is required');
        const result = await autoMatchTransactions(companyId, bankAccountId, reconciliationId);
        return apiResponse.success(res, result);
      }
      case 'allocate': {
        const aType: AllocationType = allocationType || 'account';
        if (aType === 'account' && !contraAccountId) {
          return apiResponse.badRequest(res, 'contraAccountId is required for account allocation');
        }
        if ((aType === 'supplier' || aType === 'customer') && !entityId) {
          return apiResponse.badRequest(res, 'entityId is required for supplier/customer allocation');
        }
        if (!bankTransactionId) {
          return apiResponse.badRequest(res, 'bankTransactionId is required');
        }
        const result = await allocateTransaction(
          companyId, bankTransactionId, contraAccountId || '', userId, description, aType, entityId, vatCode,
          cc1Id, cc2Id, buId,
        );
        return apiResponse.success(res, result);
      }
      case 'split_allocate': {
        const { bankTransactionId: splitTxId, lines: splitLines } = req.body as {
          bankTransactionId?: string;
          lines?: SplitLine[];
        };
        if (!splitTxId || !splitLines || !Array.isArray(splitLines) || splitLines.length === 0) {
          return apiResponse.badRequest(res, 'bankTransactionId and lines[] (non-empty) are required');
        }
        const splitResult = await splitAllocateTransaction(companyId, splitTxId, splitLines, userId);
        return apiResponse.success(res, splitResult);
      }
      case 'delete': {
        const { bankTransactionIds } = req.body;
        const ids: string[] = bankTransactionIds || (bankTransactionId ? [bankTransactionId] : []);
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionId or bankTransactionIds required');
        const deleted = await deleteTransactions(companyId, ids);
        return apiResponse.success(res, { deleted });
      }
      case 'bulk_accept': {
        const { bankTransactionIds: bulkIds } = req.body;
        const ids: string[] = Array.isArray(bulkIds) ? bulkIds : [];
        if (ids.length === 0) return apiResponse.badRequest(res, 'bankTransactionIds (array) required');
        const accepted = await bulkAcceptTransactions(companyId, ids);
        return apiResponse.success(res, { accepted });
      }
      case 'update_notes': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const { notes } = req.body as { notes?: string };
        await sql`
          UPDATE bank_transactions
          SET notes = ${notes || null}, updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
        `;
        log.info('Updated bank transaction notes', { bankTransactionId }, 'accounting-api');
        return apiResponse.success(res, { updated: true });
      }
      case 'save_selection': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        const selType: string = req.body.selectionType || 'account';
        const selEntityId: string | null = req.body.selectionEntityId || null;
        const selVatCode: string | null = req.body.vatCode || null;
        await sql`
          UPDATE bank_transactions
          SET suggested_gl_account_id = ${selType === 'account' && selEntityId ? selEntityId : null}::UUID,
              suggested_supplier_id = ${selType === 'supplier' && selEntityId ? selEntityId : null}::UUID,
              suggested_client_id = ${selType === 'customer' && selEntityId ? selEntityId : null}::UUID,
              suggested_vat_code = ${selVatCode},
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND status IN ('imported', 'allocated') AND company_id = ${companyId}
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'save_dimensions': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await sql`
          UPDATE bank_transactions
          SET cc1_id = ${cc1Id || null}::UUID,
              cc2_id = ${cc2Id || null}::UUID,
              bu_id = ${buId || null}::UUID,
              updated_at = NOW()
          WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
        `;
        return apiResponse.success(res, { saved: true });
      }
      case 'reverse': {
        if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId required');
        await reverseReconciledTransaction(companyId, bankTransactionId, userId);
        return apiResponse.success(res, { reversed: true });
      }
      default:
        return apiResponse.badRequest(res, `Unknown action: ${action}`);
    }
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Action failed';
    log.error('Bank transaction action failed', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Reconciliation Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { detectBankFormat, parseFNBStatement, parseStandardBankStatement, parseNedbankStatement, parseABSAStatement, parseCapitecStatement } from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import { runAutoMatch } from '../utils/autoMatch';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type { BankTransaction, BankReconciliation, AutoMatchResult, BankFormat, BankCsvParseResult } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Import ───────────────────────────────────────────────────────────────────

export async function importBankStatement(
  companyId: string,
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    for (const tx of parseResult.transactions) {
      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `;
    }

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import bank statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Import from Pre-Parsed Result (PDF) ──────────────────────────────────────

/**
 * Persist an already-parsed set of transactions (e.g. from a PDF import).
 * Reuses the same INSERT logic as importBankStatement so behaviour is identical.
 */
export async function importParsedTransactions(
  companyId: string,
  parseResult: BankCsvParseResult,
  bankAccountId: string,
  statementDate: string,
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    for (const tx of parseResult.transactions) {
      await sql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `;
    }

    log.info('Imported parsed bank statement', {
      batchId,
      format: parseResult.bankFormat,
      count: parseResult.transactions.length,
      statementDate,
    }, 'accounting');

    return {
      batchId,
      transactionCount: parseResult.transactions.length,
      errors: parseResult.errors,
    };
  } catch (err) {
    log.error('Failed to import parsed bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Bank Transactions ────────────────────────────────────────────────────────

interface BankTxFilters {
  bankAccountId?: string;
  reconciliationId?: string;
  status?: string;
  fromDate?: string;
  toDate?: string;
  /** Minimum transaction amount (inclusive). Defaults to unbounded when absent. */
  fromAmount?: string;

/**
 * Sage-style bank transaction table with inline allocation
 * Type selector: Account / Supplier / Customer — Selection dropdown changes accordingly
 * VAT selector: No VAT / Standard 15% / Zero-Rated / Exempt
 * Notes: inline-editable per row, saved on blur
 */

import { useState, useRef, useEffect } from 'react';
import { Check, X, Undo2, Search, Scissors, SearchCheck, RotateCcw, Paperclip, BookmarkPlus, Plus } from 'lucide-react';

export type AllocType = 'account' | 'supplier' | 'customer';
export type VatCode = 'none' | 'standard' | 'zero_rated' | 'exempt';

export const VAT_OPTIONS: { value: VatCode; label: string; rate: number }[] = [
  { value: 'none', label: 'No VAT', rate: 0 },
  { value: 'standard', label: 'Standard 15%', rate: 15 },
  { value: 'zero_rated', label: 'Zero Rated', rate: 0 },
  { value: 'exempt', label: 'Exempt', rate: 0 },
];

export interface BankTx {
  id: string;
  transactionDate: string;
  description?: string;
  reference?: string;
  bankReference?: string;
  amount: number;
  status: string;
  /** Reason recorded when this transaction was excluded */
  excludeReason?: string;
  /** User-editable memo field from bank_transactions.notes */
  notes?: string;
  /** Suggestion fields — populated by rules or classified import */
  suggestedGlAccountId?: string;
  suggestedGlAccountName?: string;
  suggestedGlAccountCode?: string;
  suggestedSupplierId?: string;
  suggestedSupplierName?: string;
  suggestedClientId?: string;
  suggestedClientName?: string;
  suggestedCategory?: string;
  suggestedVatCode?: string;
  /** Smart categorization confidence score (0-1) */
  suggestedConfidence?: number;
  /** Dimension fields */
  cc1Id?: string;
  cc2Id?: string;
  buId?: string;
  cc1Name?: string;
  cc2Name?: string;
  buName?: string;
  /** Allocation tracking — populated for matched/reconciled transactions */
  allocationType?: AllocType;
  allocatedEntityName?: string;
}

export interface SelectOption {
  id: string;
  code?: string;
  name: string;
  defaultVatCode?: string;
}

export interface RowSelection {
  type: AllocType;
  entityId: string;
  label: string;
  vatCode: VatCode;
  cc1Id?: string;
  cc2Id?: string;
  buId?: string;
}

interface Props {
  transactions: BankTx[];
  glAccounts: SelectOption[];
  suppliers: SelectOption[];
  customers: SelectOption[];
  cc1Options: SelectOption[];
  cc2Options: SelectOption[];
  buOptions: SelectOption[];
  selectedIds: Set<string>;
  rowSelections: Record<string, RowSelection>;
  allSelected: boolean;
  tab: 'new' | 'reviewed' | 'excluded';
  onToggleSelect: (id: string) => void;
  onSelectAll: () => void;
  onRowTypeChange: (txId: string, type: AllocType) => void;
  onRowEntityChange: (txId: string, entityId: string, label: string) => void;
  onRowVatChange: (txId: string, vatCode: VatCode) => void;
  onRowDimensionChange: (txId: string, cc1Id: string, cc2Id: string, buId: string) => void;
  onAccept: (txId: string) => void;
  onExclude: (txId: string) => void;
  onUnmatch: (txId: string) => void;
  onSplit: (txId: string) => void;
  /** Called when the user finishes editing the notes field for a row */
  onUpdateNotes?: (txId: string, notes: string) => void;
  onFindMatch?: (txId: string) => void;
  onReverse?: (txId: string) => void;
  onAttachments?: (txId: string) => void;

