/**
 * PRD-060: FibreFlow Accounting Module
 * Chart of Accounts Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { cacheThrough, cache } from '@/lib/cache';
import { CACHE_KEYS, CACHE_TTL } from '@/lib/cache-keys';
import type { GLAccount, GLAccountType } from '../types/gl.types';

export interface CreateAccountInput {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentAccountId?: string;
  description?: string;
  normalBalance: 'debit' | 'credit';
}

export interface UpdateAccountInput {
  accountName?: string;
  description?: string;
  isActive?: boolean;
  displayOrder?: number;
  defaultVatCode?: 'none' | 'standard' | 'zero_rated' | 'exempt';
}

interface AccountTreeNode extends GLAccount {
  children: AccountTreeNode[];
}

export async function getChartOfAccounts(companyId: string, includeInactive = false): Promise<GLAccount[]> {
  const cacheKey = includeInactive
    ? CACHE_KEYS.glAccountsInactive(companyId)
    : CACHE_KEYS.glAccounts(companyId);

  return cacheThrough(cacheKey, async () => {
    try {
      let rows;
      if (includeInactive) {
        rows = await sql`
          SELECT a.*,
            p.account_code AS parent_code,
            p.account_name AS parent_name
          FROM gl_accounts a
          LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
          WHERE a.company_id = ${companyId}
          ORDER BY a.account_code
        `;
      } else {
        rows = await sql`
          SELECT a.*,
            p.account_code AS parent_code,
            p.account_name AS parent_name
          FROM gl_accounts a
          LEFT JOIN gl_accounts p ON p.id = a.parent_account_id
          WHERE a.company_id = ${companyId}
            AND a.is_active = true
          ORDER BY a.account_code
        `;
      }
      return (rows as { [key: string]: unknown }[]).map(mapRow);
    } catch (err) {
      log.error('Failed to get chart of accounts', { error: err }, 'accounting');
      throw err;
    }
  }, CACHE_TTL.REFERENCE_DATA);
}

export async function getAccountTree(companyId: string, includeInactive = false): Promise<AccountTreeNode[]> {
  const accounts = await getChartOfAccounts(companyId, includeInactive);
  const map = new Map<string, AccountTreeNode>();
  const roots: AccountTreeNode[] = [];

  for (const acc of accounts) {
    map.set(acc.id, { ...acc, children: [] });
  }

  for (const acc of accounts) {
    const node = map.get(acc.id)!;
    if (acc.parentAccountId) {
      const parent = map.get(acc.parentAccountId);
      if (parent) {
        parent.children.push(node);
        continue;
      }
    }
    roots.push(node);
  }

  return roots;
}

export async function getAccountById(companyId: string, id: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE id = ${id} AND company_id = ${companyId}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by id', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountByCode(code: string): Promise<GLAccount | null> {
  try {
    const rows = await sql`SELECT * FROM gl_accounts WHERE account_code = ${code}`;
    const arr = rows as { [key: string]: unknown }[];
    return arr.length > 0 ? mapRow(arr[0]!) : null;
  } catch (err) {
    log.error('Failed to get account by code', { code, error: err }, 'accounting');
    throw err;
  }
}

export async function createAccount(companyId: string, input: CreateAccountInput): Promise<GLAccount> {
  try {
    const existing = await sql`
      SELECT id FROM gl_accounts WHERE account_code = ${input.accountCode} AND company_id = ${companyId}
    `;
    if ((existing as unknown[]).length > 0) {
      throw new Error(`Account code ${input.accountCode} already exists`);
    }

    let level = 1;
    if (input.parentAccountId) {
      const parent = await sql`
        SELECT id, level FROM gl_accounts WHERE id = ${input.parentAccountId}
      ` as { level: number }[];
      if (parent.length === 0) {
        throw new Error(`Parent account ${input.parentAccountId} not found`);
      }
      level = Number(parent[0]!.level) + 1;
    }

    const rows = await sql`
      INSERT INTO gl_accounts (
        company_id, account_code, account_name, account_type, account_subtype,
        parent_account_id, description, normal_balance, level
      ) VALUES (
        ${companyId}, ${input.accountCode}, ${input.accountName}, ${input.accountType},
        ${input.accountSubtype || null}, ${input.parentAccountId || null},
        ${input.description || null}, ${input.normalBalance}, ${level}
      )
      RETURNING *
    `;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to create account', { error: err }, 'accounting');
    throw err;
  }
}

export async function updateAccount(companyId: string, id: string, input: UpdateAccountInput): Promise<GLAccount> {
  try {
    const account = await sql`SELECT * FROM gl_accounts WHERE id = ${id} AND company_id = ${companyId}` as {
      is_system_account: boolean;
    }[];
    if (account.length === 0) throw new Error(`Account ${id} not found`);

    if (account[0]!.is_system_account && input.isActive === false) {
      throw new Error('Cannot deactivate a system account');
    }

    const rows = await sql`
      UPDATE gl_accounts SET
        account_name = COALESCE(${input.accountName || null}, account_name),
        description = COALESCE(${input.description ?? null}, description),
        is_active = COALESCE(${input.isActive ?? null}, is_active),
        display_order = COALESCE(${input.displayOrder ?? null}, display_order),
        default_vat_code = COALESCE(${input.defaultVatCode || null}, default_vat_code)
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
    return mapRow((rows as { [key: string]: unknown }[])[0]);
  } catch (err) {
    log.error('Failed to update account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function deleteAccount(companyId: string, id: string): Promise<void> {
  try {
    const lines = await sql`
      SELECT COUNT(*) AS cnt FROM gl_journal_lines WHERE gl_account_id = ${id}
    ` as { cnt: string }[];
    if (Number(lines[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with existing journal entries');
    }

    const children = await sql`
      SELECT COUNT(*) AS cnt FROM gl_accounts WHERE parent_account_id = ${id} AND is_active = true
    ` as { cnt: string }[];
    if (Number(children[0]!.cnt) > 0) {
      throw new Error('Cannot delete account with active child accounts');
    }

    await sql`UPDATE gl_accounts SET is_active = false WHERE id = ${id} AND company_id = ${companyId}`;
    cache.invalidatePrefix(`${companyId}:gl-accounts`);
  } catch (err) {
    log.error('Failed to delete account', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getAccountBalance(
  accountId: string,
  fiscalPeriodId?: string
): Promise<{ debitTotal: number; creditTotal: number; balance: number }> {
  try {
    let rows: { debit_total: string; credit_total: string; balance: string }[];
    if (fiscalPeriodId) {
      rows = await sql`
        SELECT debit_total, credit_total, balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId} AND fiscal_period_id = ${fiscalPeriodId}
      ` as typeof rows;
    } else {
      rows = await sql`
        SELECT
          COALESCE(SUM(debit_total), 0) AS debit_total,
          COALESCE(SUM(credit_total), 0) AS credit_total,
          COALESCE(SUM(balance), 0) AS balance
        FROM gl_account_balances
        WHERE gl_account_id = ${accountId}
      ` as typeof rows;
    }

    if (rows.length === 0) {
      return { debitTotal: 0, creditTotal: 0, balance: 0 };
    }

    return {
      debitTotal: Number(rows[0]!.debit_total),
      creditTotal: Number(rows[0]!.credit_total),
      balance: Number(rows[0]!.balance),
    };
  } catch (err) {
    log.error('Failed to get account balance', { accountId, error: err }, 'accounting');
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function mapRow(row: any): GLAccount {
  return {
    id: String(row.id),
    accountCode: String(row.account_code),
    accountName: String(row.account_name),
    accountType: String(row.account_type) as GLAccountType,
    accountSubtype: row.account_subtype ? String(row.account_subtype) : undefined,
    parentAccountId: row.parent_account_id ? String(row.parent_account_id) : undefined,
    isActive: Boolean(row.is_active),
    isSystemAccount: Boolean(row.is_system_account),
    description: row.description ? String(row.description) : undefined,
    normalBalance: String(row.normal_balance) as 'debit' | 'credit',
    level: Number(row.level),
    displayOrder: Number(row.display_order),
    bankAccountNumber: row.bank_account_number ? String(row.bank_account_number) : undefined,
    defaultVatCode: (row.default_vat_code || 'none') as GLAccount['defaultVatCode'],
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Smart Categorization API
 * GET  — get suggestions for a single transaction
 * POST — bulk categorize transactions or learn from allocation
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  categorizeBankTransaction,
  bulkCategorize,
  smartCategorizeForAccount,
  learnFromAllocation,
} from '@/modules/accounting/services/smartCategorizationService';
import { sql } from '@/lib/neon';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  // ── GET: Single transaction suggestion ─────────────────────────────────────
  if (req.method === 'GET') {
    const { txId } = req.query;
    if (!txId || typeof txId !== 'string') {
      return apiResponse.badRequest(res, 'txId query parameter required');
    }

    try {
      const txRows = (await sql`
        SELECT id, description, amount, reference
        FROM bank_transactions WHERE id = ${txId}::UUID AND company_id = ${companyId}
      `) as Row[];

      if (txRows.length === 0) {
        return apiResponse.notFound(res, 'Transaction', txId);
      }

      const tx = txRows[0];
      const result = await categorizeBankTransaction(companyId, {
        description: String(tx.description || ''),
        amount: Number(tx.amount),
        reference: tx.reference ? String(tx.reference) : undefined,
      });

      return apiResponse.success(res, {
        transactionId: txId,
        suggestion: result,
      });
    } catch (err) {
      log.error('Smart categorize GET failed', { txId, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Failed');
    }
  }

  // ── POST: Bulk categorize or learn ─────────────────────────────────────────
  if (req.method === 'POST') {
    const { action, transactionIds, bankAccountId, txId, glAccountId, category, vatCode } = req.body;

    try {
      switch (action || 'categorize') {
        case 'categorize': {
          // If bankAccountId provided, categorize all uncategorized for that account
          if (bankAccountId) {
            const result = await smartCategorizeForAccount(companyId, bankAccountId);
            return apiResponse.success(res, result);
          }
          // Otherwise, categorize specific transaction IDs
          if (!Array.isArray(transactionIds) || transactionIds.length === 0) {
            return apiResponse.badRequest(res, 'transactionIds array or bankAccountId required');
          }
          const result = await bulkCategorize(companyId, transactionIds);
          return apiResponse.success(res, result);
        }

        case 'learn': {
          if (!txId || !glAccountId || !category) {
            return apiResponse.badRequest(res, 'txId, glAccountId, and category required');
          }
          await learnFromAllocation(companyId, txId, glAccountId, category, vatCode);
          return apiResponse.success(res, { learned: true });
        }

        default:
          return apiResponse.badRequest(res, `Unknown action: ${action}`);
      }
    } catch (err) {
      log.error('Smart categorize POST failed', { action, error: err }, 'accounting-api');
      return apiResponse.badRequest(res, err instanceof Error ? err.message : 'Action failed');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Phase 2: Bank Categorisation Rules Service
 * Quick entry rules + statement mapping for auto-categorisation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type {
  BankCategorisationRule, RuleCreateInput, RuleApplyResult,
} from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── CRUD ────────────────────────────────────────────────────────────────────

export async function getRules(companyId: string): Promise<BankCategorisationRule[]> {
  const rows = (await sql`
    SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name,
           s.company_name AS supplier_name, c.name AS client_name
    FROM bank_categorisation_rules r
    LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
    LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN customers c ON c.id = r.client_id
    WHERE r.company_id = ${companyId}::UUID
    ORDER BY r.priority ASC, r.rule_name ASC
  `) as Row[];
  return rows.map(mapRuleRow);
}

export async function createRule(companyId: string, input: RuleCreateInput, userId: string): Promise<BankCategorisationRule> {
  const vatCode = input.vatCode || 'none';
  const rows = (await sql`
    INSERT INTO bank_categorisation_rules (
      company_id, rule_name, match_field, match_type, match_pattern,
      gl_account_id, supplier_id, client_id, description_template,
      priority, auto_create_entry, vat_code, created_by
    ) VALUES (
      ${companyId}::UUID, ${input.ruleName}, ${input.matchField}, ${input.matchType}, ${input.matchPattern},
      ${input.glAccountId || null}::UUID, ${input.supplierId ? Number(input.supplierId) : null},
      ${input.clientId || null}::UUID,
      ${input.descriptionTemplate || null},
      ${input.priority || 100}, ${input.autoCreateEntry !== false}, ${vatCode}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Created bank rule', { id: rows[0].id, ruleName: input.ruleName }, 'accounting');
  return mapRuleRow(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<RuleCreateInput>): Promise<BankCategorisationRule> {
  const rows = (await sql`
    UPDATE bank_categorisation_rules SET
      rule_name = COALESCE(${input.ruleName || null}, rule_name),
      match_field = COALESCE(${input.matchField || null}, match_field),
      match_type = COALESCE(${input.matchType || null}, match_type),
      match_pattern = COALESCE(${input.matchPattern || null}, match_pattern),
      gl_account_id = COALESCE(${input.glAccountId || null}::UUID, gl_account_id),
      supplier_id = COALESCE(${input.supplierId ? Number(input.supplierId) : null}, supplier_id),
      client_id = COALESCE(${input.clientId || null}::UUID, client_id),
      description_template = COALESCE(${input.descriptionTemplate || null}, description_template),
      priority = COALESCE(${input.priority || null}, priority),
      auto_create_entry = COALESCE(${input.autoCreateEntry ?? null}, auto_create_entry),
      vat_code = COALESCE(${input.vatCode || null}, vat_code)
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRuleRow(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM bank_categorisation_rules WHERE id = ${id}::UUID`;
}

export async function deleteRules(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  const rows = await sql`
    DELETE FROM bank_categorisation_rules
    WHERE id = ANY(${ids}::UUID[])
    RETURNING id
  ` as { id: string }[];
  return rows.length;
}

export async function toggleRule(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE bank_categorisation_rules SET is_active = ${isActive} WHERE id = ${id}::UUID`;
}

// ── Apply Rules ─────────────────────────────────────────────────────────────

/** Lookup a GL account UUID by account code */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Row[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0].id);
}

/** Convert rule match type to SQL ILIKE pattern */
function toSqlPattern(matchType: string, matchPattern: string): string {
  switch (matchType) {
    case 'contains': return `%${matchPattern}%`;
    case 'starts_with': return `${matchPattern}%`;
    case 'ends_with': return `%${matchPattern}`;
    case 'exact': return matchPattern;
    default: return `%${matchPattern}%`;
  }
}

export async function applyRules(companyId: string, 
  bankAccountId: string,
  userId: string
): Promise<RuleApplyResult> {
  try {
    // Get active rules ordered by priority
    const rules = (await sql`
      SELECT * FROM bank_categorisation_rules
      WHERE is_active = true
      ORDER BY priority ASC
    `) as Row[];

    if (rules.length === 0) return { applied: 0, skipped: 0, entries: [] };

    let totalApplied = 0;
    const entries: RuleApplyResult['entries'] = [];

    const autoCreateRules = rules.filter((r: Row) => Boolean(r.auto_create_entry));
    const hasSuggestionRules = rules.some((r: Row) => !r.auto_create_entry);

    if (hasSuggestionRules) {
      // Single-query approach: JOIN all suggestion-mode rules against all unmatched
      // transactions in one CTE, assign the highest-priority matching rule per tx.
      // ILIKE patterns are generated inline using CASE on match_type column —
      // one network round-trip to Neon regardless of rule count.
      const updated = (await sql`
        WITH matched AS (
          SELECT
            bt.id                                              AS tx_id,
            r.gl_account_id,
            r.supplier_id,
            r.client_id,
            r.rule_name,
            r.vat_code,
            ROW_NUMBER() OVER (PARTITION BY bt.id ORDER BY r.priority ASC) AS rn
          FROM bank_transactions bt
          JOIN bank_categorisation_rules r ON (
            r.is_active = true
            AND r.auto_create_entry = false
            AND (
              (r.match_field IN ('description', 'both')
                AND bt.description ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
              OR
              (r.match_field IN ('reference', 'both')
                AND bt.reference ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
            )
          )
          WHERE bt.bank_account_id = ${bankAccountId}::UUID
            AND bt.status IN ('imported', 'allocated')
            AND bt.suggested_gl_account_id IS NULL
            AND bt.suggested_supplier_id IS NULL
            AND bt.suggested_client_id IS NULL
            AND bt.suggested_category IS NULL
        ),
        top_match AS (SELECT * FROM matched WHERE rn = 1)
        UPDATE bank_transactions bt
        SET
          suggested_gl_account_id = tm.gl_account_id,
          suggested_supplier_id   = tm.supplier_id,
          suggested_client_id     = tm.client_id,
          suggested_category      = tm.rule_name,
          suggested_vat_code      = COALESCE(tm.vat_code, 'none')
        FROM top_match tm
        WHERE bt.id = tm.tx_id
        RETURNING bt.id, tm.rule_name
      `) as Row[];

      for (const row of updated) {
        entries.push({ bankTxId: String(row.id), ruleName: String(row.rule_name), suggestion: true });
      }
      totalApplied += updated.length;

      // Backfill vat_code for already-suggested transactions (suggested before the vat_code column existed)
      await sql`
        UPDATE bank_transactions bt
        SET suggested_vat_code = r.vat_code
        FROM (
          SELECT DISTINCT ON (rule_name) rule_name, vat_code
          FROM bank_categorisation_rules
          WHERE is_active = true AND vat_code != 'none'
          ORDER BY rule_name, priority ASC
        ) r
        WHERE bt.bank_account_id = ${bankAccountId}::UUID
          AND bt.status IN ('imported', 'allocated')
          AND bt.suggested_category = r.rule_name
          AND bt.suggested_vat_code = 'none'
      `;
    }

    // Auto-create JE mode — sequential (each transaction needs its own JE)
    for (const rule of autoCreateRules) {
      const pattern = toSqlPattern(String(rule.match_type), String(rule.match_pattern));
      const field = String(rule.match_field);
      const ruleName = String(rule.rule_name);

      let matchingTxs: Row[];
      if (field === 'description') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND description ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Row[];
      } else if (field === 'reference') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND reference ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Row[];
      } else {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND (description ILIKE ${pattern} OR reference ILIKE ${pattern})
          ORDER BY transaction_date
        `) as Row[];
      }

      for (const tx of matchingTxs) {
        const totalAmount = Math.abs(Number(tx.amount));
        const isDeposit = Number(tx.amount) > 0;
        const entryDesc = rule.description_template
          ? String(rule.description_template).replace('{description}', String(tx.description || '')).replace('{amount}', totalAmount.toFixed(2))
          : `Bank: ${tx.description || 'Categorised by rule'}`;

        // VAT splitting — mirrors allocateTransaction logic
        const vatCode = String(rule.vat_code || 'none');
        const hasVat = vatCode === 'standard';
        const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
        const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
        const vatAccountKey = isDeposit ? 'vat_output' as const : 'vat_input' as const;
        const mapVatType = vatCode === 'standard' ? 'standard' as const
          : vatCode === 'zero_rated' ? 'zero_rated' as const
          : vatCode === 'exempt' ? 'exempt' as const
          : undefined;

        let lines: JournalLineInput[];
        if (isDeposit) {
          lines = [
            { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
            { glAccountId: String(rule.gl_account_id), debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ 15%`, vatType: 'standard' });
          }
        } else {
          lines = [
            { glAccountId: String(rule.gl_account_id), debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
            { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ 15%`, vatType: 'standard' });
          }
        }

        const je = await createJournalEntry(companyId, {
          entryDate: tx.transaction_date instanceof Date
            ? tx.transaction_date.toISOString().split('T')[0]
            : String(tx.transaction_date).split('T')[0],
          description: entryDesc,
          source: 'auto_bank_recon',
          lines,
        }, userId);
        await postJournalEntry('', je.id, userId);

        const bankLineRows = (await sql`
          SELECT id FROM gl_journal_lines
          WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID
          LIMIT 1
        `) as Row[];

        if (bankLineRows[0]) {
          await sql`
            UPDATE bank_transactions
            SET status = 'allocated', matched_journal_line_id = ${bankLineRows[0].id}::UUID,
                allocation_type = 'account',
                allocated_entity_name = ${ruleName},
                updated_at = NOW()
            WHERE id = ${tx.id}::UUID
          `;
        }

        entries.push({ bankTxId: String(tx.id), ruleName, journalEntryId: je.id });
        totalApplied++;
      }
    }

    // Count remaining unmatched for the skipped total
    const remaining = (await sql`
      SELECT COUNT(*) AS cnt FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status IN ('imported', 'allocated')
        AND suggested_gl_account_id IS NULL
        AND matched_journal_line_id IS NULL
    `) as Row[];
    const skipped = Number(remaining[0].cnt);

    log.info('Applied bank rules', { bankAccountId, applied: totalApplied, skipped }, 'accounting');
    return { applied: totalApplied, skipped, entries };
  } catch (err) {
    log.error('Failed to apply bank rules', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapRuleRow(row: Row): BankCategorisationRule {
  return {
    id: String(row.id),
    ruleName: String(row.rule_name),
    matchField: String(row.match_field) as BankCategorisationRule['matchField'],
    matchType: String(row.match_type) as BankCategorisationRule['matchType'],
    matchPattern: String(row.match_pattern ?? row.match_value ?? ''),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    clientId: row.client_id ? String(row.client_id) : undefined,
    descriptionTemplate: row.description_template ? String(row.description_template) : undefined,
    priority: Number(row.priority),
    isActive: Boolean(row.is_active),
    autoCreateEntry: Boolean(row.auto_create_entry),
    vatCode: (row.vat_code || 'none') as BankCategorisationRule['vatCode'],
    createdBy: row.created_by ? String(row.created_by) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
    glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * System Account Resolver
 *
 * Resolves system GL accounts by their account_subtype instead of hardcoded
 * account codes. This decouples business logic from specific numbering schemes,
 * allowing customers to use any chart of accounts numbering (Sage, Xero, etc.).
 *
 * Usage:
 *   const arAccountId = await getSystemAccountId('receivable');
 *   const arAccount   = await getSystemAccount('receivable');
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { GLAccount, GLAccountSubtype } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Subtypes that the system requires for auto-posting and reporting.
 * Each maps to exactly one system account (is_system_account = true).
 */
export type SystemAccountKey =
  | 'bank'                      // Primary bank account
  | 'receivable'                // Accounts Receivable
  | 'payable'                   // Accounts Payable
  | 'vat_input'                 // VAT Input (claimable)
  | 'vat_output'                // VAT Output (payable)
  | 'retained_earnings'         // Retained Earnings
  | 'default_revenue'           // Default revenue account
  | 'other_income'              // Other Income
  | 'default_expense'           // Default expense (Materials & Supplies)
  | 'admin_expense'             // Administrative Expenses
  | 'accumulated_depreciation'  // Accumulated Depreciation
  | 'depreciation_expense';     // Depreciation Expense

// ── In-memory cache ─────────────────────────────────────────────────────────

interface CachedAccount {
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string;
}

let cache: Map<string, CachedAccount> | null = null;
let cacheLoadedAt = 0;
const CACHE_TTL_MS = 60_000; // 1 minute

/** Clear the cache (call after chart of accounts changes) */
export function clearSystemAccountCache(): void {
  cache = null;
  cacheLoadedAt = 0;
}

async function ensureCache(): Promise<Map<string, CachedAccount>> {
  if (cache && Date.now() - cacheLoadedAt < CACHE_TTL_MS) return cache;

  const rows = (await sql`
    SELECT id, account_code, account_name, account_type, account_subtype
    FROM gl_accounts
    WHERE is_system_account = true
      AND is_active = true
      AND account_subtype IS NOT NULL
  `) as Row[];

  const map = new Map<string, CachedAccount>();
  for (const r of rows) {
    const subtype = String(r.account_subtype);
    map.set(subtype, {
      id: String(r.id),
      accountCode: String(r.account_code),
      accountName: String(r.account_name),
      accountType: String(r.account_type),
      accountSubtype: subtype,
    });
  }

  cache = map;
  cacheLoadedAt = Date.now();
  return map;
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * Get a system account by its subtype key.
 * Throws if the account is not found (misconfigured chart of accounts).
 */
export async function getSystemAccount(key: SystemAccountKey): Promise<CachedAccount> {
  const map = await ensureCache();
  const account = map.get(key);
  if (!account) {
    log.error('System account not found', { key }, 'accounting');
    throw new Error(
      `System account with subtype '${key}' not found. ` +
      `Ensure the chart of accounts has a system account with account_subtype = '${key}'.`
    );
  }
  return account;
}

/**
 * Get only the account ID for a system account.
 * Convenience wrapper for the most common use case (building journal lines).
 */
export async function getSystemAccountId(key: SystemAccountKey): Promise<string> {
  const account = await getSystemAccount(key);
  return account.id;
}

/**
 * Check whether all required system accounts are configured.
 * Returns a list of missing subtypes (empty = all good).
 */
export async function validateSystemAccounts(): Promise<string[]> {
  const required: SystemAccountKey[] = [
    'bank', 'receivable', 'payable',
    'vat_input', 'vat_output', 'retained_earnings',
    'default_revenue', 'default_expense', 'admin_expense',
  ];

  const map = await ensureCache();
  return required.filter(key => !map.has(key));
}

/**
 * Smart Categorization Service
 * AI-powered bank transaction categorization using rules, patterns, and historical learning
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW';

export interface CategorizationInput {
  description: string;
  amount: number;
  reference?: string;
}

export interface CategorizationResult {
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  category?: string;
  vatCode?: string;
  confidence: number;
  confidenceLevel: ConfidenceLevel;
  matchSource: 'rule' | 'pattern' | 'historical';
  matchDetail?: string;
}

export interface BulkCategorizationResult {
  categorized: number;
  skipped: number;
  results: Array<{
    transactionId: string;
    result: CategorizationResult | null;
  }>;
}

// ── Confidence helpers ───────────────────────────────────────────────────────

function toConfidenceLevel(score: number): ConfidenceLevel {
  if (score >= 0.85) return 'HIGH';
  if (score >= 0.60) return 'MEDIUM';
  return 'LOW';
}

// ── Core: Categorize a single transaction ────────────────────────────────────

export async function categorizeBankTransaction(companyId: string, 
  tx: CategorizationInput
): Promise<CategorizationResult | null> {
  const description = (tx.description || '').toUpperCase().trim();
  const reference = (tx.reference || '').toUpperCase().trim();

  if (!description && !reference) return null;

  // 1. Check existing bank_categorisation_rules (highest priority)
  const ruleMatch = await matchAgainstRules(description, reference);
  if (ruleMatch) return ruleMatch;

  // 2. Check categorization_patterns table (system + learned patterns)
  const patternMatch = await matchAgainstPatterns(description, reference);
  if (patternMatch) return patternMatch;

  // 3. Learn from historical allocations (similar past transactions)
  const historicalMatch = await matchFromHistory(description, tx.amount);
  if (historicalMatch) return historicalMatch;

  return null;
}

// ── Strategy 1: Match against bank_categorisation_rules ──────────────────────

async function matchAgainstRules(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const rules = (await sql`
      SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
      WHERE r.is_active = true
      ORDER BY r.priority ASC
    `) as Row[];

    for (const rule of rules) {
      const pattern = String(rule.match_pattern).toUpperCase();
      const matchType = String(rule.match_type);
      const matchField = String(rule.match_field);

      const targets: string[] = [];
      if (matchField === 'description' || matchField === 'both') targets.push(description);
      if (matchField === 'reference' || matchField === 'both') targets.push(reference);

      const matched = targets.some(target => {
        switch (matchType) {
          case 'contains': return target.includes(pattern);
          case 'starts_with': return target.startsWith(pattern);
          case 'ends_with': return target.endsWith(pattern);
          case 'exact': return target === pattern;
          default: return target.includes(pattern);
        }
      });

      if (matched) {
        return {
          glAccountId: rule.gl_account_id ? String(rule.gl_account_id) : undefined,
          glAccountCode: rule.gl_account_code ? String(rule.gl_account_code) : undefined,
          glAccountName: rule.gl_account_name ? String(rule.gl_account_name) : undefined,
          category: String(rule.rule_name),
          vatCode: String(rule.vat_code || 'none'),
          confidence: 0.95,
          confidenceLevel: 'HIGH',
          matchSource: 'rule',
          matchDetail: `Rule: ${rule.rule_name} (${matchType} "${rule.match_pattern}")`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: rule matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 2: Match against categorization_patterns ────────────────────────

async function matchAgainstPatterns(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const patterns = (await sql`
      SELECT cp.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM categorization_patterns cp
      LEFT JOIN gl_accounts ga ON ga.id = cp.gl_account_id
      ORDER BY cp.confidence DESC, cp.usage_count DESC
    `) as Row[];

    const combined = `${description} ${reference}`;

    for (const p of patterns) {
      const pat = String(p.pattern).toUpperCase();
      const matchType = String(p.match_type);

      let matched = false;
      switch (matchType) {
        case 'contains':
          matched = combined.includes(pat);
          break;
        case 'starts_with':
          matched = description.startsWith(pat) || reference.startsWith(pat);
          break;
        case 'regex':
          try {
            const re = new RegExp(p.pattern, 'i');
            matched = re.test(description) || re.test(reference);
          } catch {
            // WORKING: invalid regex patterns are safely skipped
            matched = false;
          }
          break;
        default:
          matched = combined.includes(pat);
      }

      if (matched) {
        const confidence = Number(p.confidence) || 0.80;

        // Update usage stats (fire-and-forget)
        sql`
          UPDATE categorization_patterns
          SET usage_count = usage_count + 1, last_used_at = NOW()
          WHERE id = ${p.id}::UUID
        `.catch(() => {});

        return {
          glAccountId: p.gl_account_id ? String(p.gl_account_id) : undefined,
          glAccountCode: p.gl_account_code ? String(p.gl_account_code) : undefined,
          glAccountName: p.gl_account_name ? String(p.gl_account_name) : undefined,
          category: p.category ? String(p.category) : undefined,
          vatCode: String(p.vat_code || 'standard'),
          confidence,
          confidenceLevel: toConfidenceLevel(confidence),
          matchSource: 'pattern',
          matchDetail: `Pattern: "${p.pattern}" (${p.source})`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: pattern matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 3: Learn from historical allocations ────────────────────────────

async function matchFromHistory(
  description: string,
  _amount: number
): Promise<CategorizationResult | null> {
  if (!description || description.length < 3) return null;

  try {
    // Extract significant words (3+ chars, skip common banking noise)
    const noiseWords = new Set([
      'THE', 'AND', 'FOR', 'FROM', 'WITH', 'PAYMENT', 'TRANSFER',
      'DEBIT', 'CREDIT', 'ORDER', 'REF', 'POS', 'PURCHASE', 'CARD',
    ]);
    const words = description
      .split(/[\s/\\,.-]+/)
      .filter(w => w.length >= 3 && !noiseWords.has(w) && !/^\d+$/.test(w));

    if (words.length === 0) return null;

    // Build search: look for allocated transactions with similar descriptions
    // Use the first 2-3 significant words for matching
    const searchWords = words.slice(0, 3);
    const likePattern = `%${searchWords.join('%')}%`;

    const historicalRows = (await sql`
      SELECT
        bt.suggested_gl_account_id,
        bt.suggested_category,
        bt.suggested_vat_code,
        bt.allocation_type,
        ga.account_code AS gl_account_code,
        ga.account_name AS gl_account_name,
        COUNT(*) AS match_count
      FROM bank_transactions bt
      LEFT JOIN gl_accounts ga ON ga.id = bt.suggested_gl_account_id
      WHERE bt.status IN ('matched', 'reconciled')
        AND bt.matched_journal_line_id IS NOT NULL
        AND bt.suggested_gl_account_id IS NOT NULL
        AND UPPER(bt.description) ILIKE ${likePattern}
      GROUP BY bt.suggested_gl_account_id, bt.suggested_category,
               bt.suggested_vat_code, bt.allocation_type,
               ga.account_code, ga.account_name
      ORDER BY match_count DESC
      LIMIT 1
    `) as Row[];

    if (historicalRows.length > 0) {
      const row = historicalRows[0];
      const matchCount = Number(row.match_count);
      // Scale confidence based on how many historical matches we found
      const baseConfidence = matchCount >= 5 ? 0.70 : matchCount >= 2 ? 0.55 : 0.40;

      return {
        glAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
        glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
        glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
        category: row.suggested_category ? String(row.suggested_category) : undefined,
        vatCode: String(row.suggested_vat_code || 'none'),
        confidence: baseConfidence,
        confidenceLevel: toConfidenceLevel(baseConfidence),
        matchSource: 'historical',
        matchDetail: `Historical: ${matchCount} similar transaction(s)`,
      };
    }
  } catch (err) {
    log.error('Smart categorization: historical matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Learn from user allocation ───────────────────────────────────────────────

export async function learnFromAllocation(companyId: string, 
  txId: string,
  glAccountId: string,
  category: string,
  vatCode?: string
): Promise<void> {
  try {
    // Get the transaction description
    const txRows = (await sql`
      SELECT description FROM bank_transactions WHERE id = ${txId}::UUID
    `) as Row[];

    if (txRows.length === 0) return;

    const description = String(txRows[0].description || '').trim();
    if (description.length < 3) return;

    // Extract a clean pattern from the description
    // Remove trailing numbers, dates, and references to get the merchant/payee name
    const pattern = extractLearningPattern(description);
    if (!pattern || pattern.length < 3) return;

    // Check if we already have this pattern
    const existing = (await sql`
      SELECT id, usage_count FROM categorization_patterns
      WHERE UPPER(pattern) = ${pattern.toUpperCase()}
        AND source = 'learned'
      LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      // Update existing pattern — increase confidence with use
      const newCount = Number(existing[0].usage_count) + 1;
      const newConfidence = Math.min(0.95, 0.60 + newCount * 0.05);
      await sql`
        UPDATE categorization_patterns
        SET gl_account_id = ${glAccountId}::UUID,
            category = ${category},
            vat_code = ${vatCode || 'standard'},
            usage_count = ${newCount},
            confidence = ${newConfidence},
            last_used_at = NOW()
        WHERE id = ${existing[0].id}::UUID
      `;
    } else {
      // Create new learned pattern
      await sql`
        INSERT INTO categorization_patterns (pattern, match_type, gl_account_id, category, vat_code, confidence, usage_count, last_used_at, source)
        VALUES (${pattern}, 'contains', ${glAccountId}::UUID, ${category}, ${vatCode || 'standard'}, 0.65, 1, NOW(), 'learned')
      `;
    }

    log.info('Learned categorization pattern', { pattern, category, glAccountId }, 'accounting');
  } catch (err) {
    log.error('Failed to learn from allocation', { txId, error: err }, 'accounting');
    // Non-critical: don't throw — learning failures should not break allocation flow
  }
}

/**
 * Extract a clean pattern from a bank transaction description.
 * Strips trailing reference numbers, dates, card numbers, etc.
 */
function extractLearningPattern(description: string): string {
  let clean = description.toUpperCase();

  // Remove common suffixes: card numbers, dates, reference numbers
  clean = clean.replace(/\b\d{4}\*+\d{4}\b/g, '');      // Card number masks
  clean = clean.replace(/\b\d{2}\/\d{2}\/\d{2,4}\b/g, ''); // Dates
  clean = clean.replace(/\b\d{6,}\b/g, '');               // Long number sequences
  clean = clean.replace(/\bREF\s*:?\s*\S+/gi, '');        // REF: xxx
  clean = clean.replace(/\bPOS\b/g, '');                   // POS prefix
  clean = clean.replace(/\bPURCHASE\b/g, '');              // PURCHASE label

  // Trim and collapse whitespace
  clean = clean.replace(/\s+/g, ' ').trim();

  // Take the first meaningful part (usually merchant name)
  const parts = clean.split(/\s{2,}/);
  return parts[0]?.trim() || clean;
}

// ── Bulk categorize ──────────────────────────────────────────────────────────

export async function bulkCategorize(companyId: string, 
  transactionIds: string[]
): Promise<BulkCategorizationResult> {
  if (transactionIds.length === 0) {
    return { categorized: 0, skipped: 0, results: [] };
  }

  // Fetch all requested transactions
  const txRows = (await sql`
    SELECT id, description, amount, reference
    FROM bank_transactions
    WHERE id = ANY(${transactionIds}::UUID[])
      AND status IN ('imported', 'allocated')
  `) as Row[];

  let categorized = 0;
  let skipped = 0;
  const results: BulkCategorizationResult['results'] = [];

  for (const tx of txRows) {
    const txId = String(tx.id);
    const input: CategorizationInput = {
      description: String(tx.description || ''),
      amount: Number(tx.amount),
      reference: tx.reference ? String(tx.reference) : undefined,
    };

    const result = await categorizeBankTransaction('', input);

    if (result) {
      // Write suggestion back to the transaction
      await sql`
        UPDATE bank_transactions SET
          suggested_gl_account_id = COALESCE(${result.glAccountId || null}::UUID, suggested_gl_account_id),
          suggested_category = COALESCE(${result.category || null}, suggested_category),
          suggested_vat_code = COALESCE(${result.vatCode || null}, suggested_vat_code),
          suggested_confidence = ${result.confidence}
        WHERE id = ${txId}::UUID
          AND suggested_gl_account_id IS NULL
      `;
      categorized++;
      results.push({ transactionId: txId, result });
    } else {
      skipped++;
      results.push({ transactionId: txId, result: null });
    }
  }

  log.info('Bulk smart categorization complete', { categorized, skipped, total: txRows.length }, 'accounting');

  return { categorized, skipped, results };
}

// ── Categorize all uncategorized transactions for a bank account ──────────────

export async function smartCategorizeForAccount(companyId: string, 
  bankAccountId: string
): Promise<BulkCategorizationResult> {
  // Get all uncategorized transactions for this bank account
  const txRows = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND status IN ('imported', 'allocated')
      AND suggested_gl_account_id IS NULL
      AND suggested_category IS NULL
    ORDER BY transaction_date DESC
    LIMIT 500
  `) as Row[];

  const ids = txRows.map((r: Row) => String(r.id));
  return bulkCategorize('', ids);
}

/**
 * Bank Rules Seed API
 * POST /api/accounting/bank-rules-seed
 *   Seed categorisation rules from a Category Map (JSON array).
 *
 * Body: { entries: [{ originalCategory, standardCategory, glCode }] }
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, withRole, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CategoryMapEntry {
  originalCategory: string;
  standardCategory: string;
  glCode: number | string;
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const userId = req.user.id;
    const { entries } = req.body as { entries: CategoryMapEntry[] };

    if (!Array.isArray(entries) || entries.length === 0) {
      return apiResponse.badRequest(res, 'entries array is required');
    }

    let created = 0;
    let skipped = 0;
    const missingGlCodes: (number | string)[] = [];

    for (const entry of entries) {
      const pattern = String(entry.originalCategory || '').toLowerCase().trim();
      if (!pattern) { skipped++; continue; }

      const glCode = String(entry.glCode).trim();
      if (!glCode) { skipped++; continue; }

      // Look up GL account by account_code
      const glRows = (await sql`
        SELECT id FROM gl_accounts WHERE account_code = ${glCode} AND company_id = ${companyId} LIMIT 1
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      `) as any[];

      if (glRows.length === 0) {
        missingGlCodes.push(entry.glCode);
        skipped++;
        continue;
      }

      const glAccountId = String(glRows[0].id);
      const ruleName = String(entry.standardCategory || entry.originalCategory).trim();

      // UPSERT — skip if match_pattern already exists
      const existing = (await sql`
        SELECT id FROM bank_categorisation_rules
        WHERE LOWER(match_pattern) = ${pattern} AND company_id = ${companyId} LIMIT 1
      `) as any[];

      if (existing.length > 0) {
        skipped++;
        continue;
      }

      await sql`
        INSERT INTO bank_categorisation_rules (
          rule_name, match_field, match_type, match_pattern,
          gl_account_id, auto_create_entry, priority, created_by,
          company_id
        ) VALUES (
          ${ruleName}, 'description', 'contains', ${pattern},
          ${glAccountId}::UUID, false, 100, ${userId},
          ${companyId}
        )
      `;
      created++;
    }

    log.info('Seeded bank categorisation rules', { created, skipped, missingGlCodes: missingGlCodes.length }, 'accounting');

    return apiResponse.success(res, {
      created,
      skipped,
      missingGlCodes: missingGlCodes.length > 0 ? missingGlCodes : undefined,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to seed bank rules';
    log.error('Failed to seed bank rules', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

