/**
 * AI Transaction Categorization Service
 * Tiered approach: Rules (free) → Patterns → LLM (Claude API)
 * Pure business logic for prompt building, parsing, strategy selection.
 * Actual LLM calls are made by the API layer.
 */

export interface TransactionContext {
  description: string;
  amount: number;
  date: string;
  isDebit: boolean;
  bankName?: string;
  reference?: string;
}

export interface ChartOfAccountEntry {
  code: string;
  name: string;
  type: string;
}

export interface CategorizationResult {
  accountCode: string;
  accountName: string;
  confidence: number;
  reason: string;
  strategy: CategorizationStrategy;
}

export type CategorizationStrategy = 'rules' | 'patterns' | 'llm';

export interface ConfidenceLevel {
  level: 'HIGH' | 'MEDIUM' | 'LOW';
  color: 'green' | 'amber' | 'gray';
  score: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// PROMPT BUILDING
// ═══════════════════════════════════════════════════════════════════════════

export function buildCategorizationPrompt(
  tx: TransactionContext,
  accounts: ChartOfAccountEntry[],
): string {
  const direction = tx.isDebit ? 'debit (money out)' : 'credit (money in)';
  const accountList = accounts
    .map(a => `  ${a.code} - ${a.name} (${a.type})`)
    .join('\n');

  return `You are a South African bookkeeper. Categorize this bank transaction to the correct GL account.

Transaction:
- Description: ${tx.description}
- Amount: R${Math.abs(tx.amount).toFixed(2)}
- Direction: ${direction}
- Date: ${tx.date}
${tx.reference ? `- Reference: ${tx.reference}` : ''}

Chart of Accounts:
${accountList}

Respond in JSON format only:
{"accountCode": "xxxx", "accountName": "Account Name", "confidence": 0.0-1.0, "reason": "Brief explanation"}

Rules:
- Match the transaction to the most appropriate account
- Consider South African merchant names and conventions
- Confidence should reflect how certain you are (0.5 = guess, 0.9+ = very confident)
- For ${direction}, select an appropriate ${tx.isDebit ? 'expense/asset' : 'revenue/liability'} account`;
}

// ═══════════════════════════════════════════════════════════════════════════
// RESPONSE PARSING
// ═══════════════════════════════════════════════════════════════════════════

export function parseCategorizationResponse(response: string): CategorizationResult | null {
  if (!response || response.trim() === '') return null;

  try {
    // Try to extract JSON from the response (might be wrapped in markdown code blocks)
    let jsonStr = response;

    // Extract from ```json ... ``` blocks
    const jsonMatch = response.match(/```(?:json)?\s*\n?([\s\S]*?)\n?```/);
    if (jsonMatch) {
      jsonStr = jsonMatch[1]!;
    } else {
      // Try to find a JSON object in the text
      const objMatch = response.match(/\{[\s\S]*"accountCode"[\s\S]*\}/);
      if (objMatch) {
        jsonStr = objMatch[0];
      }
    }

    const parsed = JSON.parse(jsonStr);

    return {
      accountCode: String(parsed.accountCode || ''),
      accountName: String(parsed.accountName || ''),
      confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.5,
      reason: String(parsed.reason || ''),
      strategy: 'llm',
    };
  } catch {
    return null;
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// STRATEGY SELECTION
// ═══════════════════════════════════════════════════════════════════════════

const PATTERN_CONFIDENCE_THRESHOLD = 0.6;

export function selectCategorizationStrategy(input: {
  hasRuleMatch: boolean;
  hasPatternMatch: boolean;
  ruleConfidence: number;
  patternConfidence: number;
}): CategorizationStrategy {
  // Rules are always preferred (deterministic, free)
  if (input.hasRuleMatch && input.ruleConfidence > 0) return 'rules';

  // Patterns used if confidence is high enough
  if (input.hasPatternMatch && input.patternConfidence >= PATTERN_CONFIDENCE_THRESHOLD) return 'patterns';

  // Fall back to LLM
  return 'llm';
}

// ═══════════════════════════════════════════════════════════════════════════
// CONFIDENCE
// ═══════════════════════════════════════════════════════════════════════════

export function calculateConfidence(score: number): ConfidenceLevel {
  const clamped = Math.max(0, Math.min(1, score));

  if (clamped >= 0.85) return { level: 'HIGH', color: 'green', score: clamped };
  if (clamped >= 0.60) return { level: 'MEDIUM', color: 'amber', score: clamped };
  return { level: 'LOW', color: 'gray', score: clamped };
}

// ═══════════════════════════════════════════════════════════════════════════
// RESULT MERGING
// ═══════════════════════════════════════════════════════════════════════════

export function mergeCategorizationResults(results: CategorizationResult[]): CategorizationResult {
  if (results.length === 0) {
    return { accountCode: '', accountName: '', confidence: 0, reason: '', strategy: 'llm' };
  }

  if (results.length === 1) return results[0]!;

  // Rules always win if present
  const ruleResult = results.find(r => r.strategy === 'rules');
  if (ruleResult) return ruleResult;

  // Check if multiple strategies agree on the same account
  const accountCounts = new Map<string, CategorizationResult[]>();
  for (const r of results) {
    const existing = accountCounts.get(r.accountCode) || [];
    existing.push(r);
    accountCounts.set(r.accountCode, existing);
  }

  // Find the account code with most agreement
  let bestCode = '';
  let bestResults: CategorizationResult[] = [];
  for (const [code, group] of accountCounts) {
    if (group.length > bestResults.length || (group.length === bestResults.length && Math.max(...group.map(r => r.confidence)) > Math.max(...bestResults.map(r => r.confidence)))) {
      bestCode = code;
      bestResults = group;
    }
  }

  const highestConfResult = bestResults.reduce((best, r) => r.confidence > best.confidence ? r : best, bestResults[0]!);

  // Boost confidence when multiple strategies agree
  let boostedConfidence = highestConfResult.confidence;
  if (bestResults.length > 1) {
    boostedConfidence = Math.min(1, boostedConfidence + 0.1 * (bestResults.length - 1));
  }

  return {
    ...highestConfResult,
    confidence: Math.round(boostedConfidence * 100) / 100,
  };
}

/**
 * AI Transaction Categorization API
 * POST: categorize a bank transaction using tiered strategy (Rules → Patterns → Claude LLM)
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  buildCategorizationPrompt,
  parseCategorizationResponse,
  selectCategorizationStrategy,
  calculateConfidence,
  mergeCategorizationResults,
  type TransactionContext,
  type ChartOfAccountEntry,
  type CategorizationResult,
} from '@/modules/accounting/services/aiCategorizationService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { transactionId, description, amount, date } = req.body;
  if (!description) return apiResponse.badRequest(res, 'Transaction description is required');

  const companyId = (req as any).companyId as string;
  const isDebit = Number(amount || 0) < 0;

  const tx: TransactionContext = {
    description: String(description),
    amount: Number(amount || 0),
    date: String(date || new Date().toISOString().split('T')[0]),
    isDebit,
  };

  // Step 1: Check rules (match_value against description)
  let ruleResult: CategorizationResult | null = null;
  try {
    const rules = await sql`
      SELECT r.gl_account_id, r.priority, ga.account_code, ga.account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON r.gl_account_id = ga.id
      WHERE r.is_active = true AND ${tx.description} ILIKE CONCAT('%', r.match_value, '%')
      ORDER BY r.priority DESC LIMIT 1
    ` as Row[];
    if (rules[0]) {
      ruleResult = {
        accountCode: String(rules[0].account_code || ''),
        accountName: String(rules[0].account_name || ''),
        confidence: 1.0,
        reason: 'Matched bank categorisation rule',
        strategy: 'rules',
      };
    }
  } catch { /* rules table might not have data */ }

  // Step 2: Check learned patterns
  let patternResult: CategorizationResult | null = null;
  try {
    const patterns = await sql`
      SELECT p.gl_account_id, p.confidence, ga.account_code, ga.account_name
      FROM categorization_patterns p
      LEFT JOIN gl_accounts ga ON p.gl_account_id = ga.id
      WHERE ${tx.description} ILIKE CONCAT('%', p.pattern, '%')
      ORDER BY p.confidence DESC LIMIT 1
    ` as Row[];
    if (patterns[0]) {
      patternResult = {
        accountCode: String(patterns[0].account_code || ''),
        accountName: String(patterns[0].account_name || ''),
        confidence: Number(patterns[0].confidence || 0.7),
        reason: 'Matched learned pattern',
        strategy: 'patterns',
      };
    }
  } catch { /* patterns table might not have data */ }

  // Step 3: Determine if we need LLM
  const strategy = selectCategorizationStrategy({
    hasRuleMatch: !!ruleResult,
    hasPatternMatch: !!patternResult,
    ruleConfidence: ruleResult?.confidence ?? 0,
    patternConfidence: patternResult?.confidence ?? 0,
  });

  const results: CategorizationResult[] = [];
  if (ruleResult) results.push(ruleResult);
  if (patternResult) results.push(patternResult);

  let llmUsed = false;

  if (strategy === 'llm') {
    // Get chart of accounts for prompt
    const accounts = await sql`
      SELECT account_code as code, account_name as name, account_type as type
      FROM gl_accounts WHERE is_active = true AND company_id = ${companyId}::UUID
      ORDER BY account_code LIMIT 50
    ` as Row[];

    const coaEntries: ChartOfAccountEntry[] = accounts.map((a: any) => ({
      code: String(a.code), name: String(a.name), type: String(a.type),
    }));

    const prompt = buildCategorizationPrompt(tx, coaEntries);

    // Call Claude API if ANTHROPIC_API_KEY is set
    const apiKey = process.env.ANTHROPIC_API_KEY;
    if (apiKey) {
      try {
        const response = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
          },
          body: JSON.stringify({
            model: 'claude-haiku-4-5-20251001',
            max_tokens: 256,
            messages: [{ role: 'user', content: prompt }],
          }),
        });

        if (response.ok) {
          const data = await response.json() as any;
          const text = data.content?.[0]?.text || '';
          const llmResult = parseCategorizationResponse(text);
          if (llmResult) {
            results.push(llmResult);
            llmUsed = true;
          }
        }
      } catch (err) {
        log.error('Claude API call failed', { error: err }, 'ai');
      }
    } else {
      log.info('ANTHROPIC_API_KEY not set, skipping LLM categorization', {}, 'ai');
    }
  }

  const merged = mergeCategorizationResults(results);
  const confidence = calculateConfidence(merged.confidence);

  log.info('AI categorization completed', {
    description: tx.description,
    strategy,
    llmUsed,
    result: merged.accountCode,
    confidence: merged.confidence,
  }, 'ai');

  return apiResponse.success(res, {
    ...merged,
    confidenceLevel: confidence,
    strategyUsed: strategy,
    llmUsed,
  });
}

