                  <div className="flex gap-1 mb-1">
                    {[0, 1, 2, 3].map(i => (
                      <div
                        key={i}
                        className={`h-1 flex-1 rounded-full transition-colors ${
                          i < strength.score ? STRENGTH_COLORS[strength.score] : 'bg-gray-700'
                        }`}
                      />
                    ))}
                  </div>
                  {strength.hint && (
                    <p className="text-xs text-gray-500">{strength.hint}</p>
                  )}
                </div>
              )}
