/**
 * Approval Workflow Service
 * Configurable approval rules for financial documents.
 * Checks if documents require approval before processing.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type DocumentType = 'customer_invoice' | 'supplier_invoice' | 'payment' | 'journal_entry' | 'credit_note';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'cancelled';

export interface ApprovalRule {
  id: string;
  name: string;
  documentType: DocumentType;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
  priority: number;
  createdAt: string;
}

export interface ApprovalRequest {
  id: string;
  ruleId: string;
  ruleName?: string;
  documentType: DocumentType;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: ApprovalStatus;
  requestedBy: string;
  requestedByName?: string;
  requestedAt: string;
  decidedBy: string | null;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

export interface ApprovalCheckResult {
  requiresApproval: boolean;
  matchedRule: ApprovalRule | null;
  existingRequest: ApprovalRequest | null;
}

// ── Rule CRUD ────────────────────────────────────────────────────────────────

export async function listRules(companyId?: string): Promise<ApprovalRule[]> {
  if (!companyId) return [];
  const rows = (await sql`
    SELECT * FROM approval_rules WHERE company_id = ${companyId} ORDER BY priority ASC, name ASC
  `) as Row[];
  return rows.map(mapRule);
}

export async function createRule(companyId: string, input: {
  name: string;
  documentType: DocumentType;
  conditionField?: string;
  conditionOperator?: string;
  conditionValue?: number;
  approverRole?: string;
}): Promise<ApprovalRule> {
  const rows = (await sql`
    INSERT INTO approval_rules (company_id, name, document_type, condition_field, condition_operator, condition_value, approver_role)
    VALUES (
      ${companyId}, ${input.name}, ${input.documentType},
      ${input.conditionField || 'total'}, ${input.conditionOperator || 'greater_than'},
      ${input.conditionValue || 0}, ${input.approverRole || 'admin'}
    ) RETURNING *
  `) as Row[];
  log.info('Created approval rule', { id: rows[0].id, name: input.name }, 'accounting');
  return mapRule(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<{
  name: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}>): Promise<ApprovalRule> {
  const rows = (await sql`
    UPDATE approval_rules SET
      name = COALESCE(${input.name ?? null}, name),
      condition_field = COALESCE(${input.conditionField ?? null}, condition_field),
      condition_operator = COALESCE(${input.conditionOperator ?? null}, condition_operator),
      condition_value = COALESCE(${input.conditionValue ?? null}, condition_value),
      approver_role = COALESCE(${input.approverRole ?? null}, approver_role),
      is_active = COALESCE(${input.isActive ?? null}, is_active),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRule(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM approval_rules WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

// ── Approval Check ───────────────────────────────────────────────────────────

/** Check if a document requires approval based on active rules */
export async function checkApproval(
  companyId: string,
  documentType: DocumentType,
  documentId: string,
  amount: number
): Promise<ApprovalCheckResult> {
  // Check for existing pending request
  const existing = (await sql`
    SELECT ar.*, rl.name AS rule_name
    FROM approval_requests ar
    LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
    WHERE ar.company_id = ${companyId}
      AND ar.document_type = ${documentType}
      AND ar.document_id = ${documentId}::UUID
      AND ar.status = 'pending'
    LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    return {
      requiresApproval: true,
      matchedRule: null,
      existingRequest: mapRequest(existing[0]),
    };
  }

  // Find matching active rules
  const rules = (await sql`
    SELECT * FROM approval_rules
    WHERE company_id = ${companyId}
      AND document_type = ${documentType}
      AND is_active = true
    ORDER BY priority ASC
  `) as Row[];

  for (const rule of rules) {
    const r = mapRule(rule);
    let matches = false;

    switch (r.conditionOperator) {
      case 'any':
        matches = true;
        break;
      case 'greater_than':
        matches = amount > r.conditionValue;
        break;
      case 'greater_equal':
        matches = amount >= r.conditionValue;
        break;
    }

    if (matches) {
      return {
        requiresApproval: true,
        matchedRule: r,
        existingRequest: null,
      };
    }
  }

  return { requiresApproval: false, matchedRule: null, existingRequest: null };
}

// ── Approval Requests ────────────────────────────────────────────────────────

/** Create an approval request for a document */
export async function requestApproval(companyId: string, input: {
  ruleId: string;
  documentType: DocumentType;
  documentId: string;
  documentReference?: string;
  amount?: number;
  requestedBy: string;
}): Promise<ApprovalRequest> {
  const rows = (await sql`
    INSERT INTO approval_requests (company_id, rule_id, document_type, document_id, document_reference, amount, requested_by)
    VALUES (
      ${companyId}, ${input.ruleId}::UUID, ${input.documentType}, ${input.documentId}::UUID,
      ${input.documentReference || null}, ${input.amount || null}, ${input.requestedBy}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Approval requested', {
    id: rows[0].id,
    documentType: input.documentType,
    documentId: input.documentId,
  }, 'accounting');
  return mapRequest(rows[0]);
}

/** List approval requests with optional status filter */
export async function listRequests(companyId: string, status?: ApprovalStatus): Promise<ApprovalRequest[]> {
  const rows = status
    ? (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId} AND ar.status = ${status}
        ORDER BY ar.created_at DESC
      `) as Row[]
    : (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId}
        ORDER BY ar.created_at DESC
      `) as Row[];
  return rows.map(mapRequest);
}

/** Approve or reject a request */
export async function decideRequest(companyId: string, 
  requestId: string,
  decision: 'approved' | 'rejected',
  decidedBy: string,
  notes?: string
): Promise<ApprovalRequest> {
  const rows = (await sql`
    UPDATE approval_requests SET
      status = ${decision},
      decided_by = ${decidedBy}::UUID,
      decided_at = NOW(),
      decision_notes = ${notes || null}
    WHERE id = ${requestId}::UUID AND company_id = ${companyId} AND status = 'pending'
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Request ${requestId} not found or already decided`);
  log.info('Approval decided', { id: requestId, decision }, 'accounting');
  return mapRequest(rows[0]);
}

/** Get pending approval count for dashboard badge */
export async function getPendingCount(companyId?: string): Promise<number> {
  if (!companyId) return 0;
  const rows = (await sql`
    SELECT COUNT(*) AS count FROM approval_requests WHERE company_id = ${companyId} AND status = 'pending'
  `) as Row[];
  return Number(rows[0]?.count ?? 0);
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapRule(r: Row): ApprovalRule {
  return {
    id: r.id,
    name: r.name,
    documentType: r.document_type,
    conditionField: r.condition_field,
    conditionOperator: r.condition_operator,
    conditionValue: Number(r.condition_value),
    approverRole: r.approver_role,
    isActive: r.is_active,
    priority: r.priority,
    createdAt: r.created_at,
  };
}

function mapRequest(r: Row): ApprovalRequest {
  return {
    id: r.id,
    ruleId: r.rule_id,
    ruleName: r.rule_name || undefined,
    documentType: r.document_type,
    documentId: r.document_id,
    documentReference: r.document_reference,
    amount: r.amount ? Number(r.amount) : null,
    status: r.status,
    requestedBy: r.requested_by,
    requestedByName: r.requested_by_name || undefined,
    requestedAt: r.requested_at,
    decidedBy: r.decided_by,
    decidedByName: r.decided_by_name || undefined,
    decidedAt: r.decided_at,
    decisionNotes: r.decision_notes,
  };
}

/**
 * Neon Database Client
 * Standalone serverless PostgreSQL connection for the Accounting app
 * Uses @neondatabase/serverless with retry logic and proper config
 */

import { neon, neonConfig, Pool } from '@neondatabase/serverless';
import { log } from '@/lib/logger';

// Enable connection caching for better performance
neonConfig.fetchConnectionCache = true;

// Configure transport for Node.js environments (not in browser/edge)
declare const EdgeRuntime: unknown;

const isNodeEnv =
  typeof window === 'undefined' &&
  typeof EdgeRuntime === 'undefined';

if (isNodeEnv) {
  const useHttpTransport = process.env.NEON_USE_HTTP === 'true';

  if (!useHttpTransport) {
    // WebSocket transport - faster for Node.js
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const ws = require('ws');
      neonConfig.webSocketConstructor = ws;
      log.info('Using WebSocket transport', {}, 'Neon');
    } catch {
      log.info('WebSocket not available, falling back to HTTP', {}, 'Neon');
    }
  } else {
    log.info('Using HTTP transport (NEON_USE_HTTP=true)', {}, 'Neon');
  }

  // Configure WebSocket proxy (Neon v2 protocol)
  neonConfig.wsProxy = (host: string, port: number | string) => `${host}:${port}/v2`;

  // Use secure WebSocket connections
  neonConfig.useSecureWebSocket = true;

  // Pipeline authentication for faster connections
  neonConfig.pipelineConnect = 'password';

  // Enable automatic retries on transient errors
  neonConfig.fetchFunction = async (...args: Parameters<typeof fetch>) => {
    const maxRetries = 3;
    let lastError: unknown;

    for (let i = 0; i < maxRetries; i++) {
      try {
        const response = await fetch(...args);
        if (!response.ok && response.status >= 500 && i < maxRetries - 1) {
          // Retry on server errors with exponential backoff
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
        return response;
      } catch (error) {
        lastError = error;
        if (i < maxRetries - 1) {
          // Exponential backoff: 100ms, 200ms, 400ms
          await new Promise(resolve => setTimeout(resolve, Math.pow(2, i) * 100));
          continue;
        }
      }
    }
    throw lastError || new Error('Request failed after retries');
  };
}

/**
 * Get the DATABASE_URL, throwing a clear error if not set
 */
function getDatabaseUrl(): string {
  const url = process.env.DATABASE_URL;
  if (!url) {
    throw new Error('DATABASE_URL is not set. Please configure it in your environment.');
  }
  return url;
}

/**
 * Serverless SQL client for use in API routes and edge functions.
 * Use tagged template literals: sql`SELECT * FROM table WHERE id = ${id}`
 */
export const sql = neon(getDatabaseUrl());

/**
 * Execute multiple queries in a transaction using the Neon serverless driver.
 *
 * IMPORTANT: The Neon HTTP driver is stateless — each tagged template call is an
 * independent HTTP request. Issuing BEGIN/COMMIT as separate calls does NOT
 * guarantee they run on the same connection. We use the official `transaction()`
 * API from @neondatabase/serverless which batches queries into a single HTTP request.
 *
 * @param queries - Array of query-producing functions that receive the sql client
 * @returns Array of query results
 *
 * @example
 * const results = await transaction([
 *   (sql) => sql`INSERT INTO accounts (name) VALUES (${'Cash'}) RETURNING id`,
 *   (sql) => sql`UPDATE balances SET amount = 0 WHERE account_id = ${id}`,
 * ]);
 */
export async function transaction(
  queriesFn: (txSql: typeof sql) => Array<ReturnType<typeof sql>>
): Promise<unknown[]> {
  try {
    const txClient = neon(getDatabaseUrl());
    const results = await txClient.transaction(
      (tx) => queriesFn(tx as unknown as typeof sql) as any,
      { isolationLevel: 'ReadCommitted' }
    );
    return results as unknown[];
  } catch (error) {
    log.error(
      'Transaction failed',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  }
}

/**
 * Execute a sequential, multi-step transaction using a dedicated pool client.
 *
 * Unlike `transaction()` above (which batches static queries in a single HTTP
 * round-trip), `withTransaction` allows intermediate `await` calls inside the
 * callback — necessary when later queries depend on IDs returned by earlier
 * inserts (INSERT … RETURNING id → INSERT … WHERE fk = id).
 *
 * The pool client issues genuine BEGIN / COMMIT / ROLLBACK, giving full ACID
 * guarantees. Any error thrown inside `fn` triggers an automatic ROLLBACK.
 *
 * @example
 * const invoiceId = await withTransaction(async (tx) => {
 *   const [row] = await tx`INSERT INTO invoices (total) VALUES (${total}) RETURNING id`;
 *   await tx`INSERT INTO invoice_items (invoice_id) VALUES (${row.id})`;
 *   return String(row.id);
 * });
 */
let _pool: Pool | null = null;

function getPool(): Pool {
  if (!_pool) {
    _pool = new Pool({ connectionString: getDatabaseUrl() });
  }
  return _pool;
}

// Type for a transaction-scoped sql tagged-template function
type TxSql = (strings: TemplateStringsArray, ...values: unknown[]) => Promise<unknown[]>;

export async function withTransaction<T>(fn: (tx: TxSql) => Promise<T>): Promise<T> {
  const pool = getPool();
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    // Wrap the pool client's parameterised query as a tagged-template function
    // so callers can use tx`SELECT ...` instead of raw client.query strings.
    const tx: TxSql = async (strings, ...values) => {
      let text = '';
      strings.forEach((s, i) => {
        text += s;
        if (i < values.length) text += `$${i + 1}`;
      });
      const result = await client.query(text, values as unknown[]);
      return result.rows as unknown[];
    };

    const result = await fn(tx);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    await client.query('ROLLBACK');
    log.error(
      'withTransaction rolled back',
      error instanceof Error ? { message: error.message } : { error },
      'Neon'
    );
    throw error;
  } finally {
    client.release();
  }
}

export default sql;

