/**
 * Audit Log Export API
 * GET /api/accounting/audit-log-export — Download audit log as CSV
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getAuditLog,
  logAudit,
  type AuditLogItem,
} from '@/modules/accounting/services/auditTrailService';

function escapeCsv(value: string | null | undefined): string {
  if (value == null) return '';
  const str = String(value);
  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

function formatChanges(item: AuditLogItem): string {
  if (!item.changes?.fields?.length) return '';
  return item.changes.fields
    .map(f => `${f.label}: ${f.old ?? '(empty)'} → ${f.new ?? '(empty)'}`)
    .join(' | ');
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const {
        entity_type,
        entity_id,
        user_id,
        action,
        date_from,
        date_to,
        search,
      } = req.query;

      // Fetch up to 10,000 rows for export
      const result = await getAuditLog(companyId, {
        entityType: entity_type as string | undefined,
        entityId: entity_id as string | undefined,
        userId: user_id as string | undefined,
        action: action as string | undefined,
        dateFrom: date_from as string | undefined,
        dateTo: date_to as string | undefined,
        search: search as string | undefined,
        limit: 10000,
        offset: 0,
      });

      // Log the export action itself
      void logAudit({
        companyId,
        userId: req.user.id,
        userEmail: req.user.email,
        action: 'export',
        entityType: 'audit_log',
        entityId: companyId,
        entityRef: 'audit-trail-export',
        ip: req.headers['x-forwarded-for'] as string ?? req.socket?.remoteAddress,
        userAgent: req.headers['user-agent'],
      });

      const headers = [
        'Date/Time',
        'User',
        'Action',
        'Entity Type',
        'Reference',
        'Changes',
        'IP Address',
      ];

      const csvRows = [
        headers.map(escapeCsv).join(','),
        ...result.items.map((item: AuditLogItem) =>
          [
            escapeCsv(item.createdAt),
            escapeCsv(item.userEmail ?? item.userId),
            escapeCsv(item.action),
            escapeCsv(item.entityType),
            escapeCsv(item.entityRef),
            escapeCsv(formatChanges(item)),
            escapeCsv(item.ipAddress),
          ].join(','),
        ),
      ];

      const csv = csvRows.join('\n');
      const filename = `audit-trail-${new Date().toISOString().split('T')[0]}.csv`;

      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      res.status(200).send(csv);
      return;
    } catch (err) {
      log.error('Failed to export audit log', { error: err }, 'audit-log-export-api');
      return apiResponse.badRequest(res, 'Failed to export audit log');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Archived Data API (read-only)
 * GET /api/accounting/archived-data?date_from=YYYY-MM-DD&date_to=YYYY-MM-DD&limit=50&offset=0
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getArchivedEntries } from '@/modules/accounting/services/dataArchivingService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { date_from, date_to, limit, offset } = req.query;

  try {
    const result = await getArchivedEntries(companyId, {
      dateFrom: typeof date_from === 'string' ? date_from : undefined,
      dateTo: typeof date_to === 'string' ? date_to : undefined,
      limit: limit ? Number(limit) : 50,
      offset: offset ? Number(offset) : 0,
    });
    return apiResponse.success(res, result);
  } catch (err) {
    log.error('Failed to get archived data', { companyId, error: err }, 'archived-data-api');
    return apiResponse.badRequest(res, 'Failed to retrieve archived data');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * Trial Balance Report API
 * GET /api/accounting/reports-trial-balance?fiscal_period_id=...
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { getTrialBalance } from '@/modules/accounting/services/journalEntryService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const fiscalPeriodId = req.query.fiscal_period_id as string;
    const costCentreId = req.query.cost_centre_id as string | undefined;
    const comparePeriodId = req.query.compare_period_id as string | undefined;
    if (!fiscalPeriodId) {
      return apiResponse.badRequest(res, 'fiscal_period_id is required');
    }

    const rows = await getTrialBalance(companyId,fiscalPeriodId, costCentreId || undefined);
    const totalDebit = rows.reduce((sum, r) => sum + r.debitBalance, 0);
    const totalCredit = rows.reduce((sum, r) => sum + r.creditBalance, 0);

    if (comparePeriodId) {
      const priorRows = await getTrialBalance(companyId,comparePeriodId, costCentreId || undefined);
      const priorMap = new Map(priorRows.map(r => [r.accountCode, r]));
      for (const row of rows) {
        const prior = priorMap.get(row.accountCode);
        row.priorDebitBalance = prior?.debitBalance ?? 0;
        row.priorCreditBalance = prior?.creditBalance ?? 0;
      }
    }

    return apiResponse.success(res, {
      fiscalPeriodId,
      comparePeriodId,
      rows,
      totalDebit,
      totalCredit,
    });
  } catch (err) {
    log.error('Failed to get trial balance', { error: err }, 'accounting-api');
    return apiResponse.badRequest(res, 'Failed to get trial balance');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

