/**
 * Credit Notes API
 * GET  /api/accounting/credit-notes - List credit notes (with filters)
 * POST /api/accounting/credit-notes - Create draft credit note
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getCreditNotes,
  getCreditNoteById,
  createCreditNote,
} from '@/modules/accounting/services/creditNoteService';
import type { CreditNoteStatus } from '@/modules/accounting/types/ar.types';

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const { companyId } = req as CompanyApiRequest;

  if (req.method === 'GET') {
    try {
      const { id, type, status, limit, offset } = req.query;
      if (id) {
        const note = await getCreditNoteById(companyId, id as string);
        if (!note) return apiResponse.notFound(res, 'Credit Note', id as string);
        return apiResponse.success(res, note);
      }
      const result = await getCreditNotes(companyId, {
        type: type as 'customer' | 'supplier' | undefined,
        status: status as CreditNoteStatus | undefined,
        limit: limit ? Number(limit) : undefined,
        offset: offset ? Number(offset) : undefined,
      });
      return apiResponse.success(res, result);
    } catch (err) {
      log.error('Failed to get credit notes', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, 'Failed to get credit notes');
    }
  }

  if (req.method === 'POST') {
    try {
      const { type, clientId, customerInvoiceId, supplierId, supplierInvoiceId,
        creditDate, reason, subtotal, taxRate, projectId } = req.body;

      if (!type || !creditDate || subtotal === undefined) {
        return apiResponse.badRequest(res, 'type, creditDate, and subtotal are required');
      }

      // User identity comes from JWT (req.user), never from client request body
      const userId = req.user.id;

      const creditNote = await createCreditNote(companyId, {
        type,
        clientId: clientId || undefined,
        customerInvoiceId: customerInvoiceId || undefined,
        supplierId: supplierId || undefined,
        supplierInvoiceId: supplierInvoiceId || undefined,
        creditDate,
        reason: reason || undefined,
        subtotal: Number(subtotal),
        taxRate: taxRate !== undefined ? Number(taxRate) : undefined,
        projectId: projectId || undefined,
      }, userId);

      return apiResponse.created(res, creditNote);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to create credit note';
      log.error('Failed to create credit note', { error: err }, 'accounting-api');
      return apiResponse.badRequest(res, message);
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Duplicate Merge API
 * POST /api/accounting/duplicates-merge
 *
 * Merges a duplicate entity into a primary entity, reassigning all
 * related transactions, then soft-deletes the duplicate.
 * PRD: WS-6.6 — Duplicate Detection and Merge Wizard
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import type { AuthenticatedNextApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { mergeEntities } from '@/modules/accounting/services/duplicateDetectionService';

const VALID_ENTITY_TYPES = ['customer', 'supplier', 'item'] as const;
type EntityType = typeof VALID_ENTITY_TYPES[number];

const MERGE_ALLOWED_ROLES = ['owner', 'admin', 'manager'];

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const companyReq = req as CompanyApiRequest;
  const { companyId, companyRole } = companyReq;
  const userId = (req as AuthenticatedNextApiRequest).user.id;

  // Only privileged roles can merge entities
  if (!MERGE_ALLOWED_ROLES.includes(companyRole)) {
    return apiResponse.forbidden(res, 'Only owners, admins, and managers can merge duplicate entities');
  }

  const { entityType, primaryId, duplicateId } = req.body as {
    entityType?: string;
    primaryId?: string;
    duplicateId?: string;
  };

  if (!entityType || !primaryId || !duplicateId) {
    return apiResponse.badRequest(res, 'entityType, primaryId, and duplicateId are required');
  }

  if (!VALID_ENTITY_TYPES.includes(entityType as EntityType)) {
    return apiResponse.badRequest(res, `entityType must be one of: ${VALID_ENTITY_TYPES.join(', ')}`);
  }

  if (primaryId === duplicateId) {
    return apiResponse.badRequest(res, 'primaryId and duplicateId must be different');
  }

  try {
    const result = await mergeEntities(
      companyId,
      entityType as EntityType,
      primaryId,
      duplicateId,
      userId,
    );

    log.info('Entity merge complete', {
      companyId, entityType, primaryId, duplicateId, userId,
      reassigned: result.reassignedTransactions,
    }, 'duplicates-api');

    return apiResponse.success(res, result);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to merge entities';
    log.error('Entity merge failed', { error: err, companyId, entityType, primaryId, duplicateId }, 'duplicates-api');
    return apiResponse.badRequest(res, message);
  }
}

